SELECT (SELECT count(*) FROM t1) AS t1_rows, (SELECT group_concat(rowid, ',') FROM (SELECT rowid FROM t1 WHERE t1 MATCH 'a' ORDER BY rowid)) AS t1_match_a, (SELECT count(*) FROM t2ext) AS external_rows, (SELECT group_concat(rowid, ',') FROM (SELECT rowid FROM t2 WHERE t2 MATCH 'd' ORDER BY rowid)) AS t2_match_d, (SELECT group_concat(rowid, ',') FROM (SELECT rowid FROM t2 WHERE t2 MATCH 'g' ORDER BY rowid)) AS t2_match_g, (SELECT count(*) FROM t1aux) AS t1aux_rows, (SELECT count(*) FROM t2aux) AS t2aux_rows;